import{_ as a,o as s,c as r,a3 as t}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/54GYsSx.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/asynchronism.md","filePath":"core-concepts/asynchronism.md"}'),n={name:"core-concepts/asynchronism.md"};function i(l,e,u,c,h,p){return s(),r("div",null,[...e[0]||(e[0]=[t('<h2 id="asynchronism" tabindex="-1">Asynchronism <a class="header-anchor" href="#asynchronism" aria-label="Permalink to &quot;Asynchronism&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Asynchronism.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+o+'"><br><i><a href="http://lethain.com/introduction-to-architecting-systems-for-scale/#platform_layer">Source: Intro to architecting systems for scale</a></i></p><p>Asynchronous workflows help reduce request times for expensive operations that would otherwise be performed in-line. They can also help by doing time-consuming work in advance, such as periodic aggregation of data.</p><h3 id="message-queues" tabindex="-1">Message queues <a class="header-anchor" href="#message-queues" aria-label="Permalink to &quot;Message queues&quot;">​</a></h3><p>Message queues receive, hold, and deliver messages. If an operation is too slow to perform inline, you can use a message queue with the following workflow:</p><ul><li>An application publishes a job to the queue, then notifies the user of job status</li><li>A worker picks up the job from the queue, processes it, then signals the job is complete</li></ul><p>The user is not blocked and the job is processed in the background. During this time, the client might optionally do a small amount of processing to make it seem like the task has completed. For example, if posting a tweet, the tweet could be instantly posted to your timeline, but it could take some time before your tweet is actually delivered to all of your followers.</p><p><strong><a href="https://redis.io/" target="_blank" rel="noreferrer">Redis</a></strong> is useful as a simple message broker but messages can be lost.</p><p><strong><a href="https://www.rabbitmq.com/" target="_blank" rel="noreferrer">RabbitMQ</a></strong> is popular but requires you to adapt to the &#39;AMQP&#39; protocol and manage your own nodes.</p><p><strong><a href="https://aws.amazon.com/sqs/" target="_blank" rel="noreferrer">Amazon SQS</a></strong> is hosted but can have high latency and has the possibility of messages being delivered twice.</p><h3 id="task-queues" tabindex="-1">Task queues <a class="header-anchor" href="#task-queues" aria-label="Permalink to &quot;Task queues&quot;">​</a></h3><p>Tasks queues receive tasks and their related data, runs them, then delivers their results. They can support scheduling and can be used to run computationally-intensive jobs in the background.</p><p><strong><a href="https://docs.celeryproject.org/en/stable/" target="_blank" rel="noreferrer">Celery</a></strong> has support for scheduling and primarily has python support.</p><h3 id="back-pressure" tabindex="-1">Back pressure <a class="header-anchor" href="#back-pressure" aria-label="Permalink to &quot;Back pressure&quot;">​</a></h3><p>If queues start to grow significantly, the queue size can become larger than memory, resulting in cache misses, disk reads, and even slower performance. <a href="http://mechanical-sympathy.blogspot.com/2012/05/apply-back-pressure-when-overloaded.html" target="_blank" rel="noreferrer">Back pressure</a> can help by limiting the queue size, thereby maintaining a high throughput rate and good response times for jobs already in the queue. Once the queue fills up, clients get a server busy or HTTP 503 status code to try again later. Clients can retry the request at a later time, perhaps with <a href="https://en.wikipedia.org/wiki/Exponential_backoff" target="_blank" rel="noreferrer">exponential backoff</a>.</p><h3 id="disadvantage-s-asynchronism" tabindex="-1">Disadvantage(s): asynchronism <a class="header-anchor" href="#disadvantage-s-asynchronism" aria-label="Permalink to &quot;Disadvantage(s): asynchronism&quot;">​</a></h3><ul><li>Use cases such as inexpensive calculations and realtime workflows might be better suited for synchronous operations, as introducing queues can add delays and complexity.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://www.youtube.com/watch?v=1KRYH75wgy4" target="_blank" rel="noreferrer">It&#39;s all a numbers game</a></li><li><a href="http://mechanical-sympathy.blogspot.com/2012/05/apply-back-pressure-when-overloaded.html" target="_blank" rel="noreferrer">Applying back pressure when overloaded</a></li><li><a href="https://en.wikipedia.org/wiki/Little%27s_law" target="_blank" rel="noreferrer">Little&#39;s law</a></li><li><a href="https://www.quora.com/What-is-the-difference-between-a-message-queue-and-a-task-queue-Why-would-a-task-queue-require-a-message-broker-like-RabbitMQ-Redis-Celery-or-IronMQ-to-function" target="_blank" rel="noreferrer">What is the difference between a message queue and a task queue?</a></li></ul>',20)])])}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
